WITH hits AS (
 SELECT d.volume_id v, d.document_id id FROM frus_documents f JOIN document_cache d ON d.rowid=f.rowid
 WHERE frus_documents MATCH '(USIA OR USIS OR "Information Agency" OR "Information Service" OR "Voice of America" OR "information program" OR "psychological program" OR "psychological strategy" OR "cultural exchange" OR "educational exchange")' AND d.is_front_matter=0 AND d.is_editorial_note=0 AND d.volume_id IN ('frus1945v07','frus1946v08','frus1946v09','frus1946v10','frus1947v06','frus1947v07','frus1948v06','frus1948v07','frus1948v08','frus1949v07p1','frus1949v07p2','frus1949v08','frus1949v09','frus1950v06','frus1950v07','frus1951v06p1','frus1951v06p2','frus1951v07p1','frus1951v07p2','frus1952-54v12p1','frus1952-54v12p2','frus1952-54v13p1','frus1952-54v13p2','frus1952-54v14p1','frus1952-54v14p2','frus1952-54v15p1','frus1952-54v15p2','frus1955-57v01','frus1955-57v02','frus1955-57v03','frus1955-57v03mSupp','frus1955-57v21','frus1955-57v22','frus1955-57v23p1','frus1955-57v23p2','frus1958-60v01','frus1958-60v15','frus1958-60v16','frus1958-60v17','frus1958-60v18','frus1958-60v19','frus1961-63v01','frus1961-63v02','frus1961-63v03','frus1961-63v04','frus1961-63v23','frus1961-63v24','frus1964-68v01','frus1964-68v02','frus1964-68v03','frus1964-68v04','frus1964-68v05','frus1964-68v06','frus1964-68v07','frus1964-68v26','frus1964-68v27','frus1964-68v28','frus1964-68v29p1','frus1964-68v29p2','frus1964-68v30','frus1969-76v06','frus1969-76v07','frus1969-76v08','frus1969-76v09','frus1969-76v10','frus1969-76v17','frus1969-76v18','frus1969-76v19p1','frus1969-76v19p2','frus1969-76v20','frus1969-76v42','frus1969-76ve12','frus1969-76ve13','frus1977-80v13','frus1977-80v22','frus1961-63v22')),
base AS (
 SELECT d.volume_id v, d.document_id id, substr(dd.date_iso,1,3)||'0s' dec FROM document_cache d JOIN document_dates dd ON dd.volume_id=d.volume_id AND dd.document_id=d.document_id
 WHERE d.is_front_matter=0 AND d.is_editorial_note=0 AND d.volume_id IN ('frus1945v07','frus1946v08','frus1946v09','frus1946v10','frus1947v06','frus1947v07','frus1948v06','frus1948v07','frus1948v08','frus1949v07p1','frus1949v07p2','frus1949v08','frus1949v09','frus1950v06','frus1950v07','frus1951v06p1','frus1951v06p2','frus1951v07p1','frus1951v07p2','frus1952-54v12p1','frus1952-54v12p2','frus1952-54v13p1','frus1952-54v13p2','frus1952-54v14p1','frus1952-54v14p2','frus1952-54v15p1','frus1952-54v15p2','frus1955-57v01','frus1955-57v02','frus1955-57v03','frus1955-57v03mSupp','frus1955-57v21','frus1955-57v22','frus1955-57v23p1','frus1955-57v23p2','frus1958-60v01','frus1958-60v15','frus1958-60v16','frus1958-60v17','frus1958-60v18','frus1958-60v19','frus1961-63v01','frus1961-63v02','frus1961-63v03','frus1961-63v04','frus1961-63v23','frus1961-63v24','frus1964-68v01','frus1964-68v02','frus1964-68v03','frus1964-68v04','frus1964-68v05','frus1964-68v06','frus1964-68v07','frus1964-68v26','frus1964-68v27','frus1964-68v28','frus1964-68v29p1','frus1964-68v29p2','frus1964-68v30','frus1969-76v06','frus1969-76v07','frus1969-76v08','frus1969-76v09','frus1969-76v10','frus1969-76v17','frus1969-76v18','frus1969-76v19p1','frus1969-76v19p2','frus1969-76v20','frus1969-76v42','frus1969-76ve12','frus1969-76ve13','frus1977-80v13','frus1977-80v22','frus1961-63v22') AND dd.date_iso IS NOT NULL),
hb AS (SELECT base.dec dec, base.v v FROM base JOIN hits ON hits.v=base.v AND hits.id=base.id)
SELECT b.dec, (SELECT COUNT(*) FROM hb WHERE hb.dec=b.dec) hits, COUNT(*) dated_docs,
 round(1000.0*(SELECT COUNT(*) FROM hb WHERE hb.dec=b.dec)/COUNT(*),1) per1000,
 (SELECT v||':'||COUNT(*) FROM hb WHERE hb.dec=b.dec GROUP BY v ORDER BY COUNT(*) DESC LIMIT 1) top_volume
FROM base b GROUP BY b.dec ORDER BY b.dec;
